// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 assertionId) public {

        bytes memory data = abi.encodeWithSignature("getAssertionPolicy(bytes32)", assertionId);

        (bool success, bytes memory returnData) = address(c).staticcall(data);
        require(success, "getAssertionPolicy reverted");

        (bool blockAssertion, bool arbitrateViaEscalationManager, bool discardOracle, bool validateDisputers) = abi.decode(returnData, (bool, bool, bool, bool));

        assertTrue(discardOracle == false);
    }
}
